        this.messages = messages;

        configureInputs();
        configureSendButton();
        configureGrid();
        configureDiscardDialog();

        FormLayout form = new FormLayout(nameField, emailField, phoneField, messageField);
        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
