+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.spring.annotation.VaadinSessionScope;
+import org.springframework.stereotype.Component;
+
+/**
+ * The messages sent in this browser session, kept in memory. They survive
+ * navigating between views but not a server restart.
+ */
+@Component
+@VaadinSessionScope
+public class ContactMessages {
+
+    private final List<ContactMessage> sent = new ArrayList<>();
+
+    public void add(ContactMessage message) {
+        sent.add(0, message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return List.copyOf(sent);
+    }
+}
