+package com.example.contact;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
+
+    private final ContactMessages messages;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final List<HasValue<?, String>> inputs = List.of(nameField, emailField, phoneField, messageField);
+    private final List<HasValidation> validatedFields = List.of(nameField, emailField, phoneField, messageField);
+
+    private final FormLayout form = new FormLayout(nameField, emailField, phoneField, messageField);
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog discardDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessages messages) {
+        this.messages = messages;
+
+        configureInputs();
+        configureForm();
+        configureSendButton();
+        configureGrid();
+        configureDiscardDialog();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, sendButton, grid, discardDialog);
+    }
+
+    private void configureInputs() {
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        inputs.forEach(input -> input.addValueChangeListener(event -> sendButton.setEnabled(true)));
+    }
+
+    private void configureForm() {
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(messageField, 2);
+    }
+
+    private void configureSendButton() {
+        sendButton.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        sendButton.addClickListener(event -> sendMessage());
+        // Vaadin shortcuts listen page-wide, so this also swallows Enter on the About link
+        Shortcuts.addShortcutListener(this, this::sendMessage, Key.ENTER);
+    }
+
+    private void configureGrid() {
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.addColumn(message -> message.sentAt().format(SENT_FORMAT)).setHeader("Sent");
+        grid.setItems(messages.newestFirst());
+    }
+
+    private void configureDiscardDialog() {
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add(new Paragraph("Leaving this page will throw away what you have typed."));
+        discardDialog.setCloseOnEsc(false);
+        discardDialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            discardDialog.close();
+            pendingNavigation.cancel();
+        });
+        Button discard = new Button("Discard", event -> {
+            discardDialog.close();
+            pendingNavigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        discardDialog.getFooter().add(keepEditing, discard);
+    }
+
+    private void sendMessage() {
+        // Enter reaches here too, so it must not send while Send is disabled
+        if (!sendButton.isEnabled()) {
+            return;
+        }
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String text = messageField.getValue().trim();
+
+        if (!validate(name, email, phone, text)) {
+            return;
+        }
+
+        messages.add(new ContactMessage(name, email, phone, text, LocalDateTime.now()));
+        grid.setItems(messages.newestFirst());
+
+        // Clearing the inputs fires their value listeners, which enable Send,
+        // so Send is disabled only after the inputs have been cleared.
+        inputs.forEach(input -> input.setValue(""));
+        sendButton.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validate(String name, String email, String phone, String text) {
+        validatedFields.forEach(field -> field.setInvalid(false));
+
+        if (name.isEmpty()) {
+            markInvalid(nameField, "Name is required");
+        }
+
+        if (!email.isEmpty() && !EMAIL_PATTERN.matcher(email).matches()) {
+            markInvalid(emailField, "Enter a valid e-mail address");
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            markInvalid(emailField, "Give an e-mail address or a phone number");
+        }
+
+        if (text.isEmpty()) {
+            markInvalid(messageField, "Message is required");
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(messageField, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+        }
+
+        return validatedFields.stream().noneMatch(HasValidation::isInvalid);
+    }
+
+    private static void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasTypedInput()) {
+            pendingNavigation = event.postpone();
+            discardDialog.open();
+        }
+    }
+
+    private boolean hasTypedInput() {
+        return inputs.stream().anyMatch(input -> !input.getValue().isEmpty());
+    }
+}
