+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+import java.util.regex.Pattern;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void emptyFormMarksFieldsAndSendsNothing() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        assertFalse(NotificationElement.getByText(page, "Message sent").isOpen());
+    }
+
+    @Test
+    void sendingShowsNotificationAndListsTheMessageNewestFirst() {
+        fill("Ann", "ann@example.com", "", "First message");
+        ButtonElement.getByText(page, "Send").click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        fill("Bo", "", "+358 9 1234", "Second message");
+        ButtonElement.getByText(page, "Send").click();
+
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid-cell-content",
+                new Page.LocatorOptions().setHasText("Second message"))).hasCount(1);
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+        EmailFieldElement.getByLabel(page, "Email").assertValue("");
+        ButtonElement.getByText(page, "Send").assertDisabled();
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        fill("Ann", "ann@example.com", "", "Sent with Enter");
+
+        EmailFieldElement.getByLabel(page, "Email").getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterEditing() {
+        fill("Ann", "ann@example.com", "", "Hello");
+        ButtonElement.getByText(page, "Send").click();
+        ButtonElement.getByText(page, "Send").assertDisabled();
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Bo");
+
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStays() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Ann");
+
+        aboutLink().click();
+
+        new DialogElement(page).assertOpen();
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        new DialogElement(page).assertClosed();
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+        TextFieldElement.getByLabel(page, "Name").assertValue("Ann");
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Ann");
+
+        aboutLink().click();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void browserHistoryNavigationAlsoAsksFirst() {
+        aboutLink().click();
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        page.goBack();
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+        TextFieldElement.getByLabel(page, "Name").setValue("Ann");
+
+        page.goForward();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+        new DialogElement(page).assertClosed();
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/contact$"));
+        TextFieldElement.getByLabel(page, "Name").assertValue("Ann");
+    }
+
+    @Test
+    void leavingAnEmptyFormGoesStraightToAbout() {
+        aboutLink().click();
+
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        assertFalse(page.locator("vaadin-dialog-overlay[opened]").count() > 0);
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        TextFieldElement.getByLabel(page, "Name").setValue(name);
+        EmailFieldElement.getByLabel(page, "Email").setValue(email);
+        TextFieldElement.getByLabel(page, "Phone").setValue(phone);
+        TextAreaElement.getByLabel(page, "Message").setValue(message);
+    }
+}
