+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingLinkFormAndEmptyList() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("About", find(RouterLink.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void emptyFormMarksNameEmailAndMessageAndSendsNothing() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertInvalid(name(), "Name is required");
+        assertInvalid(email(), "Give an e-mail address or a phone number");
+        assertInvalid(message(), "Message is required");
+        assertFalse(phone().isInvalid());
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void blankNameAndMessageAreRejectedWhenWhitespaceOnly() {
+        navigate(ContactView.class);
+        fill("   ", "", "+358 40 123 4567", "   ");
+
+        test(send()).click();
+
+        assertInvalid(name(), "Name is required");
+        assertInvalid(message(), "Message is required");
+        assertFalse(email().isInvalid());
+    }
+
+    @Test
+    void malformedEmailIsRejectedEvenWithAPhoneNumber() {
+        navigate(ContactView.class);
+        fill("Ann", "not-an-email", "+358 40 123 4567", "Hello");
+
+        test(send()).click();
+
+        assertInvalid(email(), "Enter a valid e-mail address");
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void aPhoneNumberAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Ann", "", "+358 40 123 4567", "Hello");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void anEmailAddressAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "Hello");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "x".repeat(501));
+
+        test(send()).click();
+
+        assertInvalid(message(), "Message must be at most 500 characters");
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validSubmissionShowsNotificationListsMessageAndClearsForm() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "+358 40 123 4567", "Hello there");
+
+        test(send()).click();
+
+        assertTrue(test(find(Notification.class).single()).getText().contains("Message sent"));
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ann", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 3));
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterTheNextEdit() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "Hello");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("Bo");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "Hello");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+        assertEquals(1, test(grid()).size());
+        assertEquals("", name().getValue());
+    }
+
+    @Test
+    void enterDoesNotSendAnInvalidMessage() {
+        navigate(ContactView.class);
+        fill("", "", "", "");
+
+        fireShortcut(Key.ENTER);
+
+        assertInvalid(name(), "Name is required");
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void newestMessageIsFirstAndListSurvivesVisitingAbout() {
+        navigate(ContactView.class);
+        fill("Ann", "ann@example.com", "", "First");
+        test(send()).click();
+        fill("Bo", "", "+358 9 1234", "Second");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Bo", test(grid()).getCellText(0, 0));
+        assertEquals("Second", test(grid()).getCellText(0, 3));
+        assertEquals("Ann", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStaysOnTheForm() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ann");
+
+        test(find(RouterLink.class).single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue(test(discardDialog()).isOpen());
+
+        test(button("Keep editing")).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ann", name().getValue());
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        navigate(ContactView.class);
+        test(message()).setValue("Half-written");
+
+        test(find(RouterLink.class).single()).click();
+        test(button("Discard")).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingAnEmptyFormDoesNotAskAnything() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse(find(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingFromCodeAlsoAsks() {
+        navigate(ContactView.class);
+        test(email()).setValue("ann@example.com");
+
+        UI.getCurrent().navigate("about");
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue(test(discardDialog()).isOpen());
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        test(name()).setValue(name);
+        test(email()).setValue(email);
+        test(phone()).setValue(phone);
+        test(message()).setValue(message);
+    }
+
+    private static void assertInvalid(TextField field, String errorMessage) {
+        assertTrue(field.isInvalid());
+        assertEquals(errorMessage, field.getErrorMessage());
+    }
+
+    private static void assertInvalid(EmailField field, String errorMessage) {
+        assertTrue(field.isInvalid());
+        assertEquals(errorMessage, field.getErrorMessage());
+    }
+
+    private static void assertInvalid(TextArea field, String errorMessage) {
+        assertTrue(field.isInvalid());
+        assertEquals(errorMessage, field.getErrorMessage());
+    }
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return button("Send");
+    }
+
+    private Button button(String text) {
+        List<Button> buttons = find(Button.class).withText(text).all();
+        assertEquals(1, buttons.size(), "expected exactly one button labelled " + text);
+        return buttons.get(0);
+    }
+
+    private Grid<ContactMessage> grid() {
+        return find(Grid.class).single();
+    }
+
+    private Dialog discardDialog() {
+        return find(Dialog.class).single();
+    }
+}
